mapper.select:
SELECT  FROM messaging_outbox
WHERE target_handler_code = #{handlerCode} AND message_id = #{messageId} AND handler_attempt >= #{handlerAttempt}
ORDER BY handler_attempt LIMIT 1

mapper.update:
UPDATE messaging_outbox
status = #{status.value}, available_at = #{availableAt.value}, sent_at = #{sentAt.value}, sent_at = NULL, last_error = #{lastError.value}, last_error = NULL, lease_id = NULL, lease_until = NULL, version = version + 1
WHERE outbox_id = #{outboxId} AND status = 'SENDING' AND lease_id = #{leaseId} AND version = #{expectedVersion}

mapper.delete:
DELETE FROM messaging_outbox
WHERE outbox_id IN (
    SELECT outbox_id FROM messaging_outbox
    WHERE status = 'SENT' AND sent_at < #{before}
    ORDER BY sent_at, outbox_id
    LIMIT #{limit}
)
